function SidebarMenuRow({
  label,
  icon,
  href,
  onAction,
  onNavigate,
}: {
  label: string;
  icon: HeaderMenuItemId;
  href?: string;
  onAction?: () => void;
  onNavigate: () => void;
}) {
  const content = (
    <>
      <span className="flex min-w-0 items-center">
        <span className="flex w-3.5 shrink-0 items-center justify-center">
          <MenuItemIcon id={icon} />
        </span>
        <span className="ml-3.5 truncate font-satoshi text-sm font-medium leading-5 tracking-normal text-gray-900">
          {label}
        </span>
      </span>
      <ChevronRightIcon className="size-2.5 shrink-0 text-gray-400" />
    </>
  );

  const rowClassName =
    "flex min-h-10 w-full items-center justify-between py-1.5 text-left transition-colors hover:opacity-80";

  if (href) {
    return (
      <Link href={href} onClick={onNavigate} className={rowClassName}>
        {content}
      </Link>
    );
  }

  return (
    <button type="button" onClick={onAction} className={rowClassName}>
      {content}
    </button>
  );
}

export function SiteHeaderSidebar({
  open,
  onClose,
  userPhone,
  onLoginSuccess,
  onLogout,
}: {
  open: boolean;
  onClose: () => void;
  userPhone?: string | null;
  onLoginSuccess?: (phone: string) => void;
  onLogout?: () => void;
}) {
  const menuItems = getHeaderMenuItems(Boolean(userPhone));
  const { openLogin } = useWishlist();

  useEffect(() => {
    if (!open) return;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") onClose();
    }

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [open, onClose]);

  return (
    <>
      <div
        className={cn(
          "fixed inset-0 z-[60] bg-gray-900/40 transition-opacity duration-200 motion-reduce:transition-none",
          open
            ? "pointer-events-auto opacity-100"
            : "pointer-events-none opacity-0",
        )}
        onClick={onClose}
        aria-hidden={!open}
      />

      <aside
        id="site-header-sidebar"
        aria-hidden={!open}
        className={cn(
          "fixed right-0 top-0 z-[70] flex h-full w-full max-w-[24.375rem] flex-col bg-white shadow-xl transition-transform duration-200 ease-out motion-reduce:transition-none",
          open ? "translate-x-0" : "translate-x-full",
        )}
      >
        <div className="relative z-20 flex shrink-0 justify-end px-10 pb-4 pt-7">
          <button
            type="button"
            aria-label="Close menu"
            onClick={onClose}
            className="flex size-10 items-center justify-center rounded-full text-hello-lime-600 transition-colors hover:bg-gray-50 hover:text-hello-lime-700"
          >
            <CloseIcon className="size-[17px]" />
          </button>
        </div>

        <div className="relative flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain px-10 pb-10">
          {userPhone ? (
            <div className="mb-4 flex items-center gap-3">
              <UserProfileAvatarIcon className="size-12 shrink-0" />
              <p className="text-base font-bold leading-6 text-gray-900">
                +91-{userPhone}
              </p>
            </div>
          ) : null}

          <nav className="flex flex-col gap-0.5">
            {menuItems.map((item) => (
              <SidebarMenuRow
                key={item.id}
                label={item.label}
                icon={item.id}
                href={item.href}
                onNavigate={onClose}
                onAction={
                  item.action === "logout"
                    ? () => {
                        onLogout?.();
                        onClose();
                      }
                    : item.action === "login"
                      ? () => {
                          onClose();
                          openLogin({
                            onSuccess: (phone) => onLoginSuccess?.(phone),
                          });
                        }
                      : undefined
                }
              />
            ))}
          </nav>

          <div
            aria-hidden
            className="pointer-events-none absolute bottom-0 left-14 select-none"
          >
            <Logo
              variant={blackWordmark}
              width={250}
              height={143}
              className="h-auto w-[17.5rem] max-w-none opacity-[0.12]"
            />
          </div>
        </div>
      </aside>
    </>
  );
}
